function oktalKeSimbolik(oktal) {
  return String(oktal).split("").map((d) => {
    const n = Number(d);
    return (n & 4 ? "r" : "-") + (n & 2 ? "w" : "-") + (n & 1 ? "x" : "-");
  }).join("");
}

