function parseBaris(baris) {
  const m = baris.match(/(Failed|Accepted) \w+ for (?:invalid user )?(\S+) from (\d{1,3}(?:\.\d{1,3}){3})/);
  if (!m) return null;
  return { status: m[1] === "Failed" ? "gagal" : "berhasil", user: m[2], ip: m[3] };
}

