function hitungGagalPerIp(daftarBaris) {
  const hasil = {};
  for (const baris of daftarBaris) {
    const m = baris.match(/Failed \w+ for (?:invalid user )?\S+ from (\d{1,3}(?:\.\d{1,3}){3})/);
    if (m) hasil[m[1]] = (hasil[m[1]] || 0) + 1;
  }
  return hasil;
}

