solution.code:
function analisisLog(baris, batas) {
  const gagalPerIp = {};
  let totalGagal = 0;
  let totalBerhasil = 0;
  const kemungkinanJebol = [];
  const pola = /(Failed|Accepted) \w+ for (?:invalid user )?\S+ from (\d{1,3}(?:\.\d{1,3}){3})/;
  for (const b of baris) {
    const m = b.match(pola);
    if (!m) continue;
    const ip = m[2];
    if (m[1] === "Failed") {
      totalGagal++;
      gagalPerIp[ip] = (gagalPerIp[ip] || 0) + 1;
    } else {
      totalBerhasil++;
      if ((gagalPerIp[ip] || 0) >= batas && !kemungkinanJebol.includes(ip)) kemungkinanJebol.push(ip);
    }
  }
  const mencurigakan = Object.keys(gagalPerIp)
    .filter((ip) => gagalPerIp[ip] >= batas)
    .sort((a, b) => gagalPerIp[b] - gagalPerIp[a]);
  return { totalGagal, totalBerhasil, gagalPerIp, mencurigakan, kemungkinanJebol };
}
